import{z as A,x as s,o as t,c as B,q as o,j as i,D as e,d as l,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"机台匹配","description":"","frontmatter":{"title":"机台匹配","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tool-matching.md","filePath":"litho/tool-matching.md","lastUpdated":1791413859000}'),h={name:"litho/tool-matching.md"};function p(d,a,c,C,D,_){const E=s("Mermaid");return t(),B("div",null,[a[2]||(a[2]=o('<h1 id="机台匹配" tabindex="-1">机台匹配 <a class="header-anchor" href="#机台匹配" aria-label="Permalink to &quot;机台匹配&quot;">​</a></h1><div class="epigraph"><p>同一套版、同一条胶，换一台扫描仪，CD 和套刻指纹会换一张脸。匹配不是把两台调成同一序列号，是把指纹差压进预算。</p><footer>—— 据 Levinson, Principles of Lithography 对套刻与机台匹配（mix-and-match）的讨论整理</footer></div><p><a href="/litho/reticle-library-exchange">上一课</a>把版换进机。缺口是多机：量产不会只活在一台上。本课钉匹配，稼动率下一课。匹配的对象是指纹而不是精度：每台都在规格内，两台的差仍能吃光套刻预算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>照明瞳、镜头像差、台网格、剂量标定各台不同。混流后层间套刻和 CD 出现「机台条」。只校准单机到规格，不保证两机差。</p><p>展开：机台指纹来自四层——光学层（照明瞳与像差）、几何层（网格、正交、放大率、焦面）、设置层（剂量、焦点零点）、时间层（漂移方向各异）。混流后批在机台间弹跳，按机台分组的系统差在套刻账上现形（<a href="/litho/tool-to-tool-overlay">机台对机台套刻</a>）。规格内不等于可混：\\(\\pm\\) 窗口里两台各站一角，机差可达窗口全宽——只校准单机到规格，不保证两机差。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选参考机，测照明、剂量、套刻网格、焦点。用校正表（照明、放大率、扫描同步偏置）把差压进剩余。统计：匹配残差进 SPC，超限停混流。与 <a href="/litho/scanner-calibration-cycle">扫描仪校准周期</a> 分工：校准是单机回到自己的零，匹配是两机相对零。</p><p>工程流程：选稳定高产的机台当参考机，用片上计量（裸片网格加产品套刻标记）测出两台指纹；差值分解成低阶（平移、放大、旋转、正交）与高阶（<a href="/litho/high-order-overlay">高阶套刻</a>项）逐层写校正表：照明与剂量差改设置，网格差改模型，像差差覆盖不了就退回专机专用。</p>',9)),(t(),i(n,null,{default:e(()=>[r(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REF%5B%22%E5%8F%82%E8%80%83%E6%9C%BA%E6%8C%87%E7%BA%B9%22%5D%20--%3E%20DELTA%5B%22%E6%9C%BA%E5%B7%AE%22%5D%0A%20%20DUT%5B%22%E5%BE%85%E9%85%8D%E6%9C%BA%E6%8C%87%E7%BA%B9%22%5D%20--%3E%20DELTA%0A%20%20DELTA%20--%3E%20CORR%5B%22%E6%A0%A1%E6%AD%A3%E8%A1%A8%22%5D%0A%20%20CORR%20--%3E%20MIX%5B%22%E5%85%81%E8%AE%B8%E6%B7%B7%E6%B5%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p><span class="marginnote">匹配不是把 A 机调成 B 机：校正表在各机自己的坐标系里解释同一目标，参考机只在定义坐标系时用一次——匹配因此隔着数周的计量滞后仍有效，它约束指纹，不是实时状态。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><span class="marginnote">「指纹」可以想象成笔迹：两台机都写得工整（都在规格内），但写同一个字时笔画的歪法不一样。量产要的是两台机的字能叠在一起用，所以匹配管的是「笔迹差」，不是「谁更工整」。</span></p><p><span class="marginnote">常见误区：以为匹配就是「把 B 机再校准一遍」。校准是让每台回到自己的零；匹配是让两台的零彼此靠近。只校准不匹配，两个各自「准」的机台加起来仍可能吃光套刻预算。</span></p><p>像差指纹通过 TCC 进 CD；网格指纹进套刻。校正若只做低阶（放大、旋转），高阶像差差仍在。High-NA 半场机差更刺眼。</p><p>写透一点：两条账分开管——像差指纹经 TCC 进 CD，匹配动照明与剂量；网格指纹进套刻，动网格与正交；混在一张表里改，按下葫芦浮起瓢。校正阶数必须覆盖混流敏感的指纹：只做低阶时，两台的高阶像差差原样留在片上，表现为随场位置弯曲的套刻残差。机差还会 fading：镜头老化、换件、两台校准漂移方向不同，会慢慢吃掉匹配好的预算——匹配是带保质期的状态，不是一次性调平。High-NA 半场靠拼接（<a href="/litho/high-na-stitch">High-NA 拼接</a>）拼出全片，机差直接落进拼接缝，更刺眼。</p>',6)),(t(),i(n,null,{default:e(()=>[r(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20AB%5B%22%E5%83%8F%E5%B7%AE%E6%8C%87%E7%BA%B9%22%5D%20--%3E%7C%E7%BB%8F%20TCC%7C%20CDD%5B%22CD%20%E6%9C%BA%E5%B7%AE%22%5D%0A%20%20GR%5B%22%E7%BD%91%E6%A0%BC%E6%8C%87%E7%BA%B9%22%5D%20--%3E%20OV%5B%22%E5%A5%97%E5%88%BB%E6%9C%BA%E5%B7%AE%22%5D%0A%20%20CDD%20--%3E%20FI%5B%22%E6%94%B9%E7%85%A7%E6%98%8E%E4%B8%8E%E5%89%82%E9%87%8F%22%5D%0A%20%20OV%20--%3E%20GA%5B%22%E6%94%B9%E7%BD%91%E6%A0%BC%E4%B8%8E%E6%AD%A3%E4%BA%A4%22%5D%0A%20%20FI%20--%3E%20RES%5B%22%E7%89%87%E4%B8%8A%E5%89%A9%E4%BD%99%E6%9C%BA%E5%B7%AE%22%5D%0A%20%20GA%20--%3E%20RES%0A%20%20HO%5B%22%E9%AB%98%E9%98%B6%E5%83%8F%E5%B7%AE%E5%B7%AE%E6%9C%AA%E8%A6%86%E7%9B%96%22%5D%20--%3E%20RES%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p><span class="marginnote">为什么重要：匹配省下的复测计量看似是几小时的节省，实际是把风险转成几批套刻超限的报废。镜头老化与漂移方向不同让机差悄悄涨回来，匹配因此要按保质期管理，不是调平一次就归档。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>匹配只在同代同型机台间充分有效：跨代混流时照明自由度与像差量级差太远，校正表通常只敢接网格与放大率，其余靠工艺裕度硬吃。本课不写套刻计量的取样与建模（<a href="/litho/overlay-budget">套刻预算</a>课域）；CD 机差与套刻机差分开归账，别用一张匹配表包打天下。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>匹配管的是机差，不是单机绝对精度。</li><li>校正阶数必须覆盖混流敏感的指纹。</li><li>下一课稼动率：匹配再好，机台不在线就没有产能。</li><li>出处：套刻与照明课；校准周期课。</li></ul>',5))])}const T=A(h,[["render",p]]);export{f as __pageData,T as default};
